window.YANTRA_SCHEMA_NOTES = {
  "overview_note": "Every table with its keyed columns, and every link. Use the area tabs for all columns.",
  "areas": [
    {"name": "Equipment", "note": "Sites and units, the register tree, classes, types, makers, models, meter types, the meters of models and nodes and their readings, properties with their options, class links, model values and items' own values, history and files, and one-point lessons (S075). Tables of other areas show their primary key only."},
    {"name": "Team and access", "note": "People, trades, site roles and units, devices for push. Tables of other areas show their primary key only."},
    {"name": "Tickets", "note": "Breakdowns and defects, their timeline, labour, parts, assignees and codes, and the improvements that analyse them (S067) with their why-why chain and root cause (S069) and their countermeasures (S070), their timeline and the verified close (S072). Tables of other areas show their primary key only."},
    {"name": "System", "note": "Settings, serial counters, the job queue and the access log. No foreign keys. Tables of other areas show their primary key only."}
  ],
  "tables": {
    "access_log": {"area": "System", "holds": "One row per sighting of a login session from an address, or a refusal (S013); kept 365 days"},
    "app_settings": {"area": "System", "holds": "Escalation times, upload limits, internal networks, label settings, etc."},
    "class_properties": {"area": "Equipment", "holds": "Class → property links (S043, v31), one row per pair (primary key). No active flag: *Remove* deletes the link, and the models' values of it stay"},
    "db_version": {"area": "System", "holds": "The migrations applied (internal)"},
    "equipment": {"area": "Equipment", "holds": "Register fields, `level` (equipment / component-unit / component), `parent_id` for the tree, `unit_id` (equipment only), `model_id` (required on equipment and components, optional on component-units, S033 v28 CHECK), `class_id` and `type_id` (copied from the model, S012; picked directly when a component-unit has no model, S033), lifecycle (S030), criticality"},
    "equipment_categories": {"area": "Equipment", "holds": "A group of equipment classes (ISO 14224 equipment category, S063 v35): name (unique without regard to case), active. Nothing seeded; deactivating is refused while an active class is in it"},
    "equipment_classes": {"area": "Equipment", "holds": "Code (= the equipment-code prefix, e.g. `VBM`), name, `category_id` (optional, S063 v35), active"},
    "equipment_documents": {"area": "Equipment", "holds": "Files attached to equipment, an equipment model (S012), a ticket (photos, S017), a countermeasure (`action_id`, S070, v38: a photo of the work) or a one-point lesson (`procedure_id`, S075, v41) — exactly one owner (`chk_equipment_documents_owner` counts the five columns; indexes `ix_equipment_documents_action (action_id, removed_at)`, `ix_equipment_documents_procedure (procedure_id, removed_at)`): kind (document / photo), title (editable), original name, system-generated stored name, type, size, thumbnail flag; created / updated / removed who and when — removal hides, the file stays (S006); a removed document is restored or deleted for good (row and file, logged) by the manager or IT admin from Settings (S008)"},
    "equipment_events": {"area": "Equipment", "holds": "Equipment history: one row per move or change of lifecycle, criticality or class — old → new, who, when (S002); since v30 also `meter_added`, `meter_removed` and `meter_limits` (the limits in force on both sides, S038); since v33 `property` (an item's own property value set, changed or cleared: \"<property>: <value>\" on each side, the model's value in force marked \"(model)\", S044)"},
    "equipment_models": {"area": "Equipment", "holds": "Manufacturer, designation (unique per maker), class, optional type of that class — all but the designation fixed after creation; active (S012)"},
    "equipment_property_values": {"area": "Equipment", "holds": "An equipment item's own value of a property of its class (S044, v33), where its nameplate differs from its model's; it wins over the model's on that item only. One row per item and property (primary key `(equipment_id, property_id)`); the same value columns, CHECKs (`chk_equipment_property_one_value`, and since v34 `chk_equipment_property_geo_pair` and `chk_equipment_property_geo_range`) and option foreign key `(option_id, property_id)` as `model_property_values`. No row = the model's value applies. A model or class change leaves the rows alone: a value of a property the new class lacks is hidden, not deleted. Each set, change and clear writes a `property` event"},
    "equipment_types": {"area": "Equipment", "holds": "Per class: name, active (S004); `equipment.type_id` must be a type of the equipment's class"},
    "failure_causes": {"area": "Tickets", "holds": "Causes (S016): code, label, description, ISO cause group, active"},
    "failure_modes": {"area": "Tickets", "holds": "Symptoms (S016): code, label, description, class (NULL = General), active"},
    "improvement_actions": {"area": "Tickets", "holds": "The countermeasures of an improvement (S070, v38; ISO 9001 § 10.2.1 c): kind (`correction`, `corrective`, `preventive`, `design_out`, `lesson`, `spread`), what will be done (up to 500), owner (→ `people`: any active member of the site, with or without a login), due date, state (`open`, `done`, `cancelled`; done and cancelled are final). Done: what was done (up to 1000), when, who recorded it — all three set exactly when done (`chk_improvement_actions_done`). Cancelled: reason (up to 500), when, who — all three set exactly when cancelled (`chk_improvement_actions_cancelled`). Who added it and when; the last change of the plan (kind, text, owner, due date). Never deleted (ISO 9001 § 7.5.3); at most 30 per improvement (the API). Overdue is computed, never stored. S074 (v40) adds `overdue_alert_for` (DATE NULL, after `due_date`): the due date the daily scan queued *Countermeasure overdue* for, so it is sent once per due date; NULL = never; a due date that moves alerts again. Written without `updated_*`. Indexes `ix_improvement_actions_improvement (improvement_id, id)`, `ix_improvement_actions_owner_state (owner_id, state, due_date)` (*my open countermeasures*)"},
    "improvement_events": {"area": "Tickets", "holds": "The timeline of an improvement (S072, v39; as `ticket_events`; ISO 9001 § 7.5.3): one line per change, written by every write of the API in the same transaction. `event` (`started`, `edited`, `ticket_linked`, `ticket_removed`, `why_added`, `why_changed`, `why_removed`, `root_cause_set`, `root_cause_changed`, `action_added`, `action_changed`, `action_done`, `action_cancelled`, `state_changed`, `note`, `closed_effective`, `closed_not_effective`, `dropped`), `occurred_at` (an `action_done` line: its done time), `from_state`/`to_state` (state lines), `ticket_id` (→ `tickets`) and `action_id` (→ `improvement_actions`) for the line's ticket or countermeasure, `remark` (the new text) and `earlier` (the replaced text), who and when. No why id: a removed why's row is deleted, so its line carries its text. Only inserted, never changed. Migration v39 backfilled the lines the earlier rows show (started, ticket linked, why added, root cause set, countermeasure added, done, cancelled). Index `ix_improvement_events_improvement (improvement_id, occurred_at, id)`"},
    "improvement_tickets": {"area": "Tickets", "holds": "Improvement → the tickets it analyses (S067, v36), primary key `(improvement_id, ticket_id)`, who added it and when. `open_link` is 1 while the improvement is open and NULL after (the closes and the drop set it, S072); the unique key `uq_improvement_tickets_open (ticket_id, open_link)` lets a ticket be in only one open improvement, and `chk_improvement_tickets_open_link` allows only 1 or NULL. Removing a ticket deletes its row; the ticket row is never written"},
    "improvement_whys": {"area": "Tickets", "holds": "The why-why chain of an improvement (S069, v37; TPM why-why): one line per *Why? / Because*, `position` 1..n with no gap (`chk_improvement_whys_position` ≥ 1; kept by the API under the improvement's lock, no unique key), question (up to 300), answer (up to 1000), evidence (up to 500, NULL when none), who wrote it and when, who changed it last and when. A removed why is deleted (since S072 its text stays on the timeline, `improvement_events`). Index `ix_improvement_whys_position (improvement_id, position)`"},
    "improvements": {"area": "Tickets", "holds": "An improvement (S067, v36; TPM focused improvement): one problem analysed from one or more tickets. Serial `IM-YYYY-MM-NNN` (`uq_improvements_serial`), the unit and the machine of the first ticket (fixed; the site is the unit's), state (S072, v39: `analysing`, `actions_open`, `watching` (open), `closed_effective`, `closed_not_effective`, `dropped`; *ready to verify* is computed from the clock, never stored), title (up to 120), problem (up to 2000), lead (a person who may hold `improvement:edit` at the site when picked), who started it and when, last edit. Never deleted. Indexes `ix_improvements_unit_state`, `ix_improvements_equipment`. The tickets' symptom, cause and downtime are read from the tickets, never copied. S069 (v37) adds the root cause: `root_cause` (text, up to 500) and `root_cause_id` (→ `failure_causes`, the list the tickets use), both set or both NULL (`chk_improvements_root_cause`), set and changed but never cleared; index `ix_improvements_root_cause` (the cause's code freeze counts through it); and `contributing_causes` (free text, up to 2000, NULL when none). S072 (v39) adds the watch: `watch_days` (30–365, default 90, `chk_improvements_watch_days`) and `watch_from` (set exactly in `watching` and the two closes, `chk_improvements_watch_from`; a drop keeps it or not); the close: `closed_at`, `closed_by` (both set exactly in the three closed states, `chk_improvements_closed`) and `close_remark` (up to 1000, required for `closed_not_effective` and `dropped`, `chk_improvements_close_remark`); and `follow_up_of_id` (→ `improvements`, the improvement a *not effective* close started this one from; unique, `uq_improvements_follow_up`, so one follow-up each). A state change stamps no `updated_*`. S074 (v40) adds `ready_alert_for` (DATETIME NULL, after `watch_from`): the watch end the daily scan (`improvement_alert_scan`) queued *Ready to verify* for, so it is sent once per watch end; NULL = never; a watch end that moves alerts again. Written without `updated_*`"},
    "maintenance_actions": {"area": "Tickets", "holds": "Actions (S016): code, label, description, active"},
    "manufacturers": {"area": "Equipment", "holds": "Makers: name (unique without regard to case), active (S012). Generic and in-house makers are ordinary rows"},
    "memberships": {"area": "Team and access", "holds": "Person → site: the person's one role at that site, and \"all units\" (S011 A1)"},
    "meter_readings": {"area": "Equipment", "holds": "A node's meter readings (S039, v32): node (`equipment_id`) and meter type (S038: a meter's identity is the pair), `value` (`DECIMAL(14,3)`; a Yes / No reading stores 1 for Yes and 0 for No, the API shows the words), `taken_at` (IST, to the minute; up to 7 days back), `is_reset` (a counter's *Meter reset*), `limit_state` (`low` / `high` for a gauge outside its limits, `not_ok` for an answer other than the expected one; stored at saving, so a later limit change never re-judges a reading), `source` (`manual` today; `pm`, `move`, `iiot` later), `note` (up to 200), who and when. Never deleted: a removal sets `removed_at` / `removed_by`, and the rules then ignore the reading. No unique key on the time (a removed reading may share its minute with its replacement); two active readings at one minute are refused in code. Index `ix_meter_readings_meter_time` (node, meter type, time). A link to a PM job's result row comes with PM (phase 4)"},
    "meter_types": {"area": "Equipment", "holds": "The catalogue of meter types (S037, v29), edited in Masters: name (unique without regard to case), unit (NULL exactly when the kind is `yes_no`), kind (`counter` / `gauge` / `amount` (*Amount per period*) / `yes_no`), expected answer (`yes` / `no`, Yes / No types only), decimals 0–3, active. A CHECK keeps a Yes / No type without unit or decimals and with an expected answer, and every other kind with a unit and no expected answer. Eight seed rows, `created_by` `migration-v29`. Kind, unit, decimals and expected answer cannot change once a model meter or node meter uses the type (S038). Readings are in `meter_readings` (S039, v32)"},
    "model_meters": {"area": "Equipment", "holds": "A model's meters (S038, v30): model, meter type (one row per model and type, `uq_model_meters`), a gauge's default `min_value` / `max_value` (`DECIMAL(14,3)`, each optional, NULL on other kinds; a CHECK keeps min ≤ max), active (*Remove* sets it inactive; an add of the type brings the row back). Every equipment of the model has these meters, computed live, never copied"},
    "model_property_values": {"area": "Equipment", "holds": "A model's value of a property (S043, v31), one row per model and property (primary key): exactly one of `value_number` (`DECIMAL(16,4)`), `value_text` (up to 100), `value_bool`, `option_id` and, since v34, `value_lat` is filled (`chk_model_property_one_value`); which one follows the property's data type (checked in the code). A Location (`geo`, v34) is `value_lat` `DECIMAL(8,6)` and `value_lng` `DECIMAL(9,6)`: both or neither (`chk_model_property_geo_pair`), latitude −90 to 90 and longitude −180 to 180 (`chk_model_property_geo_range`). The option's foreign key is `(option_id, property_id)`, so it must be this property's. No row = no value. Shown on the equipment page's *Properties* card, where an item's own value (`equipment_property_values`) wins"},
    "node_meters": {"area": "Equipment", "holds": "A node's own meter rows (S038, v30), one per node and meter type (`uq_node_meters`): `own` 1 = a meter added on this node (*This machine only*), `own` 0 = an override of its model meter's limits, kept only while it differs from the model; `min_value` / `max_value` as `model_meters`; active (an own meter removed: inactive, limits cleared). `own` never changes after insert"},
    "people": {"area": "Team and access", "holds": "The Team register: one record per person, or per contractor firm (the user's choice): name, employment (direct / contractor), optional Yantra login set by IT admin, active (S010 A1); email, copied from the Keycloak login token at each login, never typed, shown only to IT admin and its owner (S032, v27)"},
    "person_trades": {"area": "Team and access", "holds": "Person → trades, none or more (S010 A1)"},
    "person_units": {"area": "Team and access", "holds": "Person → unit: the units within a site where the person has a membership without \"all units\" (S011 A1)"},
    "procedures": {"area": "Equipment", "holds": "The Procedures master (Plan § 4.3a); today only its first kind, the one-point lesson (S075, v41; TPM one-point lesson). Serial `OPL-NNN`, one plant-wide series (`uq_procedures_serial`; past 999 the number grows), `kind` (`one_point_lesson`; later kinds append their value), the machine it was written on (`equipment_id` → `equipment`, any node, never changed), `class_id` (→ `equipment_classes`, NULL unless the lesson is shown on every machine of that class: the machine's class when ticked, TPM yokoten), title (up to 80, one line), body (plain text, up to 1000, line breaks kept), `action_id` (→ `improvement_actions`, the countermeasure of kind Lesson it was written for; NULL when none; one lesson per countermeasure, `uq_procedures_action`), `active` (the retire flag: a retired lesson leaves the machine's card but keeps its row, photos and serial), who wrote it and when, who changed it last and when. Never deleted (ISO 9001 § 7.5.3); an edit keeps no earlier text. Indexes `ix_procedures_equipment (equipment_id, active)`, `ix_procedures_class (class_id, active)`"},
    "property_definitions": {"area": "Equipment", "holds": "The property master (S043, v31), edited in Masters › Properties: the technical data a class of equipment has (ISO 14224 Annex A). Name (unique without regard to case, `uq_property_definitions_name`), data type (`number` / `choice` / `text` / `yes_no` / `geo`, a *Location*: latitude and longitude, since v34; fixed once it has an option or a value), unit (a number's only, `chk_property_unit`; fixed once a value exists), description, active (never deleted). Since v34 (S061) two flags, `TINYINT(1) NOT NULL DEFAULT 0`: `all_classes` (*Applies to every class*: shown on every equipment without a `class_properties` row) and `per_item_only` (*Value set on each machine*: never valued on a model; cannot be turned on while a model has a value). 22 seed rows, `created_by` `migration-v31`, linked to no class; one more since v34, \"GPS location\" (`geo`, both flags set, `created_by` `migration-v34`). A Location property shows only on nodes of level `equipment`"},
    "property_options": {"area": "Equipment", "holds": "A choice property's options (S043, v31): property, label (unique per property, `uq_property_options_label`), active (never deleted; an inactive one stays on the values that hold it). `uq_property_options_id_property` lets a value's option be checked against its property. The seed's five choices have their options"},
    "push_subscriptions": {"area": "Team and access", "holds": "Web push endpoints, one per person and device (S021, v24)"},
    "serial_counters": {"area": "System", "holds": "Per-scope counters (locked `FOR UPDATE`): equipment codes per class prefix (S002), `TK-` ticket serials per month (S017), `IM-` improvement serials per month (S067), `OPL-` one-point lesson serials in one plant-wide series (scope `OPL`, S075), later `PM-`"},
    "sites": {"area": "Equipment", "holds": "Code (e.g. `SMTW`, `BRICKS`), name, address, active"},
    "task_queue": {"area": "System", "holds": "Base pattern: alerts and emails (S021, S032), the daily access-log purge (S013); later PM generation and sync"},
    "ticket_assignees": {"area": "Tickets", "holds": "Ticket → people assigned, who and when (S018)"},
    "ticket_events": {"area": "Tickets", "holds": "The ticket's timeline, one row per change: event, from and to state, event time, entered at and by whom, intensity, person the line is about, remark (S017); planned date, waiting reason, machine stopped (S019); for a work note, who corrected it last and when (S027, v23)"},
    "ticket_labour": {"area": "Tickets", "holds": "Person, trade worked, work date and minutes per ticket (S018)"},
    "ticket_note_edits": {"area": "Tickets", "holds": "The earlier texts of a corrected work note: event, the text replaced, who and when (S027, v23; ISO 9001 § 7.5.3)"},
    "ticket_parts": {"area": "Tickets", "holds": "Parts fitted per ticket (S020): description, part number and its kind, maker, quantity and unit, the node fitted to"},
    "tickets": {"area": "Tickets", "holds": "Ticket (breakdown or defect, by intensity): machine, component, unit at raise, state, intensity, codes, description, reported by, serial, source (S017); cause, action, not-a-fault flag, repeat of (S018); state *scheduled*, planned date, waiting reason (S019)"},
    "trades": {"area": "Team and access", "holds": "Trades (electrician, fitter, tool maker, …), kept in the UI (S010)"},
    "units": {"area": "Equipment", "holds": "`site_id`, code (the part after the dot; the full `SITE.UNIT` code is derived), name, optional OneERP warehouse code, active"},
    "user_units": {"area": "Team and access", "holds": "Legacy (S001): username → unit. No longer used; its rows are copied into Team (`people`, `person_units`) by migration v20 (was v8; squashed S025), kept for a rollback, dropped by a later step"}
  },
  "planned_note": "Not built yet; the design is in `Plan.MD` § 4. Names may change when their step is briefed.",
  "planned": [
    {"tables": ["pm_templates", "pm_template_items"], "holds": "Reusable PM work: items in the shared item shape (§ 4.3: type task / check / reading, unit and limits, optional meter, help text, reference photo, photo setting), triggers"},
    {"tables": ["pm_plans"], "holds": "Equipment, title, kind (PM / CIL), performer (maintenance / operator), source template, triggers (calendar interval, meter + threshold, before use), default assignee"},
    {"tables": ["pm_plan_items"], "holds": "Items of a plan, same shape as template items; CIL items carry their group (C / I / L)"},
    {"tables": ["pm_jobs"], "holds": "Generated job: plan, due date or triggering reading, state, serial"},
    {"tables": ["pm_job_results"], "holds": "One row per plan item: done / OK-NotOK-NA / value by type, remark, photo link"},
    {"tables": ["pm_job_events"], "holds": "State changes, like `ticket_events`"},
    {"tables": ["pm_routes", "pm_route_plans"], "holds": "*Proposed* (§ 4.3): a named walk — performer, the plans it covers in order; jobs stay one per equipment"},
    {"tables": ["procedure_items"], "holds": "*Proposed* (§ 4.3a): a procedure's steps in the shared item shape (§ 4.3). `procedures` itself is built (S075, v41, the one-point-lesson kind); the other kinds add their columns when briefed"},
    {"tables": ["procedure_completions"], "holds": "*Proposed* (§ 4.3a): person, procedure, equipment or class, date, recorded by — onboarding done"},
    {"tables": ["breakdown_procedure_items", "breakdown_procedure_results"], "holds": "*Proposed* (§ 4.3a): a procedure's steps copied onto a ticket and their results, same shape as `pm_job_results`"},
    {"tables": ["verification_rounds", "verification_items"], "holds": "*Proposed* (§ 4.1): a walk per unit; per equipment confirmed / not found, who, when"}
  ]
};
